// ---------------------------------------------------------------------------
// GSTIN
// ---------------------------------------------------------------------------

const GSTIN_CHARS = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';

/**
 * The GSTIN check character (15th): over the first 14 characters, weights
 * alternate 1, 2, 1, 2 … from the left; each product p contributes
 * floor(p / 36) + (p mod 36); check = (36 − sum mod 36) mod 36, as a base-36
 * digit. This is the GSTN's published Luhn-mod-36 variant.
 */
export function gstinCheckChar(first14: string): string {
  if (first14.length !== 14) throw new Error('gstinCheckChar needs the first 14 characters');
  let sum = 0;
  for (let i = 0; i < 14; i++) {
    const v = GSTIN_CHARS.indexOf(first14[i]);
    if (v < 0) throw new Error(`Invalid GSTIN character '${first14[i]}'`);
    const p = v * (i % 2 === 0 ? 1 : 2);
    sum += Math.floor(p / 36) + (p % 36);
  }
  return GSTIN_CHARS[(36 - (sum % 36)) % 36];
}

export interface GstinCheck {
  valid: boolean;
  reason?: string;
  stateCode?: string;
  pan?: string;
}

/**
 * Validates a regular taxpayer's GSTIN: `SS PPPPPNNNNP E Z C`
 *  - SS  state code (must be a known code, GST_STATES)
 *  - PAN 5 letters, 4 digits, 1 letter
 *  - E   entity number for the same PAN in the state, 1–9 then A–Z
 *  - Z   default 'Z' for regular taxpayers (UIN/TDS/NRTP formats differ and are rejected)
 *  - C   check character (see gstinCheckChar)
 * Input is trimmed and upper-cased first.
 */
export function validateGstin(gstin: string): GstinCheck {
  const g = (gstin ?? '').trim().toUpperCase();
  if (g.length !== 15) return { valid: false, reason: `A GSTIN has 15 characters; this has ${g.length}` };
  if (!/^[0-9A-Z]{15}$/.test(g)) return { valid: false, reason: 'A GSTIN contains only letters and digits' };
  const stateCode = g.slice(0, 2);
  const pan = g.slice(2, 12);
  if (!/^[0-9]{2}$/.test(stateCode) || !STATE_BY_CODE.has(stateCode)) {
    return { valid: false, reason: `'${stateCode}' is not a GST state code`, pan };
  }
  if (!/^[A-Z]{5}[0-9]{4}[A-Z]$/.test(pan)) {
    return { valid: false, reason: 'Characters 3–12 must be a PAN (5 letters, 4 digits, 1 letter)', stateCode };
  }
  if (!/^[1-9A-Z]$/.test(g[12])) return { valid: false, reason: 'The 13th character (entity number) cannot be 0', stateCode, pan };
  if (g[13] !== 'Z') return { valid: false, reason: "The 14th character is 'Z' for a regular taxpayer", stateCode, pan };
  const expected = gstinCheckChar(g.slice(0, 14));
  if (g[14] !== expected) {
    return { valid: false, reason: `Check character should be '${expected}', not '${g[14]}' — likely a typo`, stateCode, pan };
  }
  return { valid: true, stateCode, pan };
}

// ---------------------------------------------------------------------------
// Place of supply
// ---------------------------------------------------------------------------

export interface PlaceOfSupply {
  stateCode: string;
  stateName: string;
  /** Supplier's registration state ≠ place of supply → IGST. */
  isInterState: boolean;
  supplierStateCode: string;
  rule: string;
}

/**
 * Place of supply for interior design (SAC 998391) and interior works
 * (SAC 9954) is the LOCATION OF THE IMMOVABLE PROPERTY — IGST Act s.12(3)(a)
 * (services directly in relation to immovable property, incl. architects and
 * interior decorators) for a domestic supplier and recipient. So it is the
 * SITE's state, not the client's billing address.
 *
 * Supplier state = the GSTIN's state code when a valid GSTIN is present (that
 * is the registration making the supply), else the supplier address.
 */
export function placeOfSupply(supplier: Party, siteAddress: Address): PlaceOfSupply {
  const site = STATE_BY_CODE.get(siteAddress.stateCode);
  if (!site) throw new Error(`Site address has an unknown GST state code '${siteAddress.stateCode}'`);
  const fromGstin = supplier.gstin ? validateGstin(supplier.gstin) : undefined;
  const supplierStateCode = fromGstin?.valid ? fromGstin.stateCode! : supplier.address.stateCode;
  if (!STATE_BY_CODE.has(supplierStateCode)) {
    throw new Error(`Supplier address has an unknown GST state code '${supplierStateCode}'`);
  }
  return {
    stateCode: site.code,
    stateName: site.name,
    isInterState: supplierStateCode !== site.code,
    supplierStateCode,
    rule: 'IGST Act 2017 s.12(3): location of the immovable property',
  };
}

// ---------------------------------------------------------------------------
// Tax split
// ---------------------------------------------------------------------------

export interface TaxSplit {
  cgst: Paise;
  sgst: Paise;
  igst: Paise;
  total: Paise;
}

/**
 * Tax on one taxable value at one rate. The total is computed once
 * (taxable × rate, half away from zero). Intra-state it is split into CGST and
 * SGST/UTGST of rate/2 each (CGST Act s.9 + SGST/UTGST Acts); the halves are
 * rounded so they always sum to the total — CGST takes the odd paisa.
 * Inter-state it is all IGST (IGST Act s.5).
 */
export function splitTax(taxable: Paise, ratePct: number, interState: boolean): TaxSplit {
  assertPaise(taxable, 'taxable value');
  if (!(ratePct >= 0)) throw new Error(`GST rate must be ≥ 0, got ${ratePct}`);
  const total = Number(divRoundBig(BigInt(taxable) * pctToMicro(ratePct), 1_000_000n));
  if (interState) return { cgst: 0, sgst: 0, igst: total, total };
  const cgst = roundHalfAway(total / 2);
  return { cgst, sgst: total - cgst, igst: 0, total };
}

// ---------------------------------------------------------------------------
// HSN / SAC digits
// ---------------------------------------------------------------------------

/**
 * HSN/SAC digits required on invoices (Notification 78/2020-CT, from 1 Apr
 * 2021): aggregate turnover in the preceding FY ≤ ₹5 crore → 4 digits,
 * > ₹5 crore → 6 digits. Codes shorter than that are returned as they are.
 */
export function hsnDigits(code: string, turnoverAbove5Cr: boolean): string {
  const digits = (code ?? '').replace(/\D/g, '');
  const n = turnoverAbove5Cr ? 6 : 4;
  return digits.length > n ? digits.slice(0, n) : digits;
}

