// Document types and declarations
// ---------------------------------------------------------------------------

/**
 * Which documents a supplier may issue:
 *  - UNREGISTERED: cannot charge GST → quotation and a plain invoice (no tax lines).
 *  - COMPOSITION (s.10 / s.10(2A)): cannot collect tax → bill of supply
 *    (s.31(3)(c), Rule 49) carrying the Rule 5(1)(g) declaration.
 *  - REGULAR: tax invoice (s.31, Rule 46) and proforma for milestone requests.
 * Quotations are estimates with no GST obligation; variation orders amend an
 * approved quote.
 */
export function allowedDocTypes(registration: GstRegistration): DocType[] {
  switch (registration) {
    case 'UNREGISTERED':
      return ['QUOTATION', 'PLAIN_INVOICE'];
    case 'COMPOSITION':
      return ['QUOTATION', 'BILL_OF_SUPPLY', 'VARIATION_ORDER'];
    case 'REGULAR':
      return ['QUOTATION', 'PROFORMA', 'TAX_INVOICE', 'VARIATION_ORDER'];
  }
}

/** Whether a document from this supplier shows GST lines at all. */
export function chargesGst(registration: GstRegistration, docType: DocType): boolean {
  return registration === 'REGULAR' && docType !== 'BILL_OF_SUPPLY' && docType !== 'PLAIN_INVOICE';
}

/**
 * CGST Rules 2017, Rule 5(1)(g): a composition taxable person shall mention
 * these words at the top of the bill of supply. (Whether the 6% services
 * composition rate and ₹50 L cap still apply in FY 2026-27 is unverified.)
 */
export const compositionDeclaration = 'composition taxable person, not eligible to collect tax on supplies';

// ---------------------------------------------------------------------------
// Financial year
// ---------------------------------------------------------------------------

/** Indian financial year (April–March) of an ISO date: '2026-10-16' → '2026-27', '2027-03-31' → '2026-27'. */
export function financialYear(isoDate: string): string {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(isoDate ?? '');
  if (!m) throw new Error(`Expected an ISO date (YYYY-MM-DD…), got '${isoDate}'`);
  const y = Number(m[1]);
  const month = Number(m[2]);
  if (month < 1 || month > 12) throw new Error(`Invalid month in '${isoDate}'`);
  const start = month >= 4 ? y : y - 1;
  return `${start}-${String((start + 1) % 100).padStart(2, '0')}`;
}
